Definition AMEMSET_STUB : Z := 0xb8578.
Definition imemset_entry := 0xb8fd0%Z.

Definition memset_icpt_stmt {HCEIL : HeapCeil} : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
